const safety = $('Safety Configuration').first().json;
const now = new Date();
const qaWorkspaceId = String(safety.qa_workspace_id || '').trim();
const qaLeadPublicId = String(safety.qa_lead_public_id || '').trim();
const qaAllowlistConfigured = Boolean(qaWorkspaceId && qaLeadPublicId);
const productionMode = safety.production_mode === true;
const qaMode = !productionMode && qaAllowlistConfigured;

const settingsRows = $items('Fetch Follow-Up Settings')
  .map((item) => item.json)
  .filter((row) => row.workspace_id);
const subscriptionRows = $items('Fetch Subscriptions')
  .map((item) => item.json)
  .filter((row) => row.workspace_id && row.plan_id);
const planRows = $items('Fetch Plans')
  .map((item) => item.json)
  .filter((row) => row.id);

const planById = new Map(planRows.map((plan) => [String(plan.id), plan]));
const subscriptionByWorkspace = new Map(
  subscriptionRows.map((subscription) => [String(subscription.workspace_id), subscription]),
);

function validTimezone(timezone) {
  try {
    new Intl.DateTimeFormat('en-CA', { timeZone: timezone }).format(now);
    return true;
  } catch {
    return false;
  }
}

const scopedWorkspaceIds = [];
const scopeDiagnostics = [];

for (const row of settingsRows) {
  const workspaceId = String(row.workspace_id);
  const subscription = subscriptionByWorkspace.get(workspaceId);
  const plan = subscription ? planById.get(String(subscription.plan_id)) : null;
  const planCode = String(plan?.code || '');
  const subscriptionStatus = String(subscription?.status || '');
  const entitled = Boolean(
    plan?.is_active === true &&
    ['trialing', 'active'].includes(subscriptionStatus) &&
    ['starter', 'pro', 'white_label'].includes(planCode)
  );
  const timezone = String(row.timezone || 'UTC').trim() || 'UTC';
  const timezoneValid = validTimezone(timezone);
  const pausedUntilMs = row.paused_until ? new Date(row.paused_until).getTime() : 0;
  const paused = Number.isFinite(pausedUntilMs) && pausedUntilMs > now.getTime();
  const qaWorkspaceMatch = qaMode && workspaceId === qaWorkspaceId;
  const productionEligible = Boolean(
    productionMode &&
    row.enabled === true &&
    entitled &&
    timezoneValid &&
    !paused
  );

  if (qaWorkspaceMatch || productionEligible) {
    scopedWorkspaceIds.push(workspaceId);
  }

  scopeDiagnostics.push({
    workspace_id: workspaceId,
    settings_enabled: row.enabled === true,
    plan_code: planCode || null,
    subscription_status: subscriptionStatus || null,
    entitled,
    timezone,
    valid_timezone: timezoneValid,
    paused,
    qa_workspace_match: qaWorkspaceMatch,
    production_eligible: productionEligible,
  });
}

const uniqueWorkspaceIds = [...new Set(scopedWorkspaceIds)];
const workspaceFilter = uniqueWorkspaceIds.length
  ? 'workspace_id=in.(' + uniqueWorkspaceIds.join(',') + ')'
  : 'workspace_id=eq.00000000-0000-0000-0000-000000000000';

return [{
  json: {
    production_mode: productionMode,
    qa_mode: qaMode,
    qa_allowlist_configured: qaAllowlistConfigured,
    qa_workspace_id: qaWorkspaceId || null,
    qa_lead_public_id: qaLeadPublicId || null,
    scoped_workspace_ids: uniqueWorkspaceIds,
    scoped_workspace_count: uniqueWorkspaceIds.length,
    workspace_filter: workspaceFilter,
    scope_diagnostics: scopeDiagnostics,
  },
}];

const safety = $('Safety Configuration').first().json;
const scope = $('Build Eligible Workspace Scope').first().json;
const now = new Date();

const qaWorkspaceId = String(safety.qa_workspace_id || '').trim();
const qaLeadPublicId = String(safety.qa_lead_public_id || '').trim();
const productionMode = safety.production_mode === true;
const qaMode = scope.qa_mode === true;
const writeEnabled = safety.write_enabled === true;
const configuredGlobalMax = Number(safety.global_max_writes_per_run || 0);
const globalMaxWrites = Math.min(
  50,
  Math.max(0, Number.isFinite(configuredGlobalMax) ? Math.floor(configuredGlobalMax) : 0),
);

const settingsRows = $items('Fetch Follow-Up Settings')
  .map((item) => item.json)
  .filter((row) => row.workspace_id);
const subscriptionRows = $items('Fetch Subscriptions')
  .map((item) => item.json)
  .filter((row) => row.workspace_id && row.plan_id);
const planRows = $items('Fetch Plans')
  .map((item) => item.json)
  .filter((row) => row.id);
const leads = $items('Fetch Active Hot Warm Leads')
  .map((item) => item.json)
  .filter((lead) => lead.id && lead.public_id && lead.workspace_id);
const activities = $items('Fetch Lead Activities')
  .map((item) => item.json)
  .filter((activity) => activity.lead_id && activity.occurred_at);
const tasks = $items('Fetch Existing Tasks')
  .map((item) => item.json)
  .filter((task) => task.lead_id && task.workspace_id);
const stages = $items('Fetch Pipeline Stages')
  .map((item) => item.json)
  .filter((stage) => stage.id);

const planById = new Map(planRows.map((plan) => [String(plan.id), plan]));
const subscriptionByWorkspace = new Map(
  subscriptionRows.map((subscription) => [String(subscription.workspace_id), subscription]),
);
const stageTypeById = new Map(stages.map((stage) => [String(stage.id), stage.stage_type]));

function isValidTimezone(timezone) {
  try {
    new Intl.DateTimeFormat('en-CA', { timeZone: timezone }).format(now);
    return true;
  } catch {
    return false;
  }
}

function localDayKey(dateValue, timezone) {
  return new Intl.DateTimeFormat('en-CA', {
    timeZone: timezone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(dateValue);
}

const runtimeByWorkspace = new Map();
for (const row of settingsRows) {
  const workspaceId = String(row.workspace_id);
  const subscription = subscriptionByWorkspace.get(workspaceId);
  const plan = subscription ? planById.get(String(subscription.plan_id)) : null;
  const planCode = String(plan?.code || '');
  const subscriptionStatus = String(subscription?.status || '');
  const entitled = Boolean(
    plan?.is_active === true &&
    ['trialing', 'active'].includes(subscriptionStatus) &&
    ['starter', 'pro', 'white_label'].includes(planCode)
  );
  const timezone = String(row.timezone || 'UTC').trim() || 'UTC';
  const validTimezone = isValidTimezone(timezone);
  const maxTasksPerRun = Math.min(25, Math.max(1, Math.floor(Number(row.max_tasks_per_run || 1))));
  const maxTasksPerDay = Math.min(200, Math.max(1, Math.floor(Number(row.max_tasks_per_day || 10))));
  const hotStaleHours = Math.min(168, Math.max(1, Number(row.hot_stale_hours || 2)));
  const warmStaleHours = Math.min(720, Math.max(1, Number(row.warm_stale_hours || 24)));
  const pausedUntilMs = row.paused_until ? new Date(row.paused_until).getTime() : 0;
  const paused = Number.isFinite(pausedUntilMs) && pausedUntilMs > now.getTime();

  runtimeByWorkspace.set(workspaceId, {
    workspace_id: workspaceId,
    enabled: row.enabled === true,
    timezone,
    valid_timezone: validTimezone,
    hot_stale_hours: hotStaleHours,
    warm_stale_hours: warmStaleHours,
    max_tasks_per_run: maxTasksPerRun,
    max_tasks_per_day: maxTasksPerDay,
    paused,
    paused_until: row.paused_until || null,
    entitled,
    plan_code: planCode || null,
    subscription_status: subscriptionStatus || null,
  });
}

const latestActivityByLead = new Map();
for (const activity of activities) {
  const timestamp = new Date(activity.occurred_at).getTime();
  const previous = latestActivityByLead.get(activity.lead_id) || 0;
  if (Number.isFinite(timestamp) && timestamp > previous) {
    latestActivityByLead.set(activity.lead_id, timestamp);
  }
}

const openTaskLeadIds = new Set(
  tasks.filter((task) => task.status === 'open').map((task) => task.lead_id),
);

const productionAutoTasksByWorkspace = new Map();
for (const task of tasks) {
  const description = String(task.description || '');
  const automationKey = String(task.automation_key || '');
  if (!automationKey.startsWith('follow-up:v1:') && !description.includes('[AUTO-FOLLOW-UP:v1:')) {
    continue;
  }
  const workspaceId = String(task.workspace_id);
  const list = productionAutoTasksByWorkspace.get(workspaceId) || [];
  list.push(task);
  productionAutoTasksByWorkspace.set(workspaceId, list);
}

const candidateGroups = new Map();
const workspaceStats = new Map();

function ensureStats(workspaceId) {
  if (!workspaceStats.has(workspaceId)) {
    const runtime = runtimeByWorkspace.get(workspaceId);
    workspaceStats.set(workspaceId, {
      workspace_id: workspaceId,
      plan_code: runtime?.plan_code || null,
      subscription_status: runtime?.subscription_status || null,
      settings_enabled: runtime?.enabled === true,
      entitled: runtime?.entitled === true,
      valid_timezone: runtime?.valid_timezone === true,
      paused: runtime?.paused === true,
      timezone: runtime?.timezone || null,
      scanned_leads: 0,
      eligible_candidates: 0,
      selected_candidates: 0,
      authorized_candidates: 0,
      today_auto_tasks: 0,
      daily_capacity_remaining: 0,
      run_capacity: runtime?.max_tasks_per_run || 0,
      skip_reason: null,
    });
  }
  return workspaceStats.get(workspaceId);
}

for (const lead of leads) {
  const workspaceId = String(lead.workspace_id);
  const stats = ensureStats(workspaceId);
  stats.scanned_leads += 1;
  const runtime = runtimeByWorkspace.get(workspaceId);

  if (!runtime) {
    stats.skip_reason = stats.skip_reason || 'missing_workspace_follow_up_settings';
    continue;
  }
  if (!runtime.valid_timezone) {
    stats.skip_reason = stats.skip_reason || 'invalid_timezone';
    continue;
  }

  const qaAllowed = Boolean(
    qaMode &&
    workspaceId === qaWorkspaceId &&
    String(lead.public_id) === qaLeadPublicId
  );
  const productionAllowed = Boolean(
    productionMode &&
    runtime.enabled &&
    runtime.entitled &&
    !runtime.paused
  );

  if (!qaAllowed && !productionAllowed) {
    if (!productionMode && !qaAllowed) stats.skip_reason = stats.skip_reason || 'qa_allowlist_miss';
    else if (!runtime.enabled) stats.skip_reason = stats.skip_reason || 'workspace_disabled';
    else if (!runtime.entitled) stats.skip_reason = stats.skip_reason || 'plan_not_entitled';
    else if (runtime.paused) stats.skip_reason = stats.skip_reason || 'workspace_paused';
    continue;
  }

  const stageType = lead.pipeline_stage_id ? stageTypeById.get(String(lead.pipeline_stage_id)) : 'open';
  if (stageType === 'won' || stageType === 'lost') continue;
  if (openTaskLeadIds.has(lead.id)) continue;

  const thresholdHours = lead.routing_status === 'Hot' ? runtime.hot_stale_hours : runtime.warm_stale_hours;
  const fallbackTouch = new Date(lead.status_changed_at || lead.created_at || 0).getTime();
  const lastTouchMs = latestActivityByLead.get(lead.id) || fallbackTouch;
  if (!Number.isFinite(lastTouchMs)) continue;

  const inactiveHours = (now.getTime() - lastTouchMs) / 3600000;
  if (inactiveHours < thresholdHours) continue;

  const dayKey = localDayKey(now, runtime.timezone);
  const keyPrefix = qaAllowed ? 'follow-up:qa:v1:' : 'follow-up:v1:';
  const automationKey = keyPrefix + [String(lead.public_id), dayKey, String(lead.routing_status)].join(':');
  const marker = '[AUTO-FOLLOW-UP:v1:' + lead.public_id + ':' + dayKey + ':' + lead.routing_status + ']';

  const duplicateExists = tasks.some((task) => {
    if (String(task.workspace_id) !== workspaceId) return false;
    if (String(task.automation_key || '') === automationKey) return true;
    return String(task.description || '').includes(marker);
  });
  if (duplicateExists) continue;

  const dueHours = lead.routing_status === 'Hot' ? 2 : 24;
  const dueAt = new Date(now.getTime() + dueHours * 3600000).toISOString();
  const group = candidateGroups.get(workspaceId) || [];
  group.push({
    json: {
      create_task: true,
      write_enabled: writeEnabled,
      production_mode: productionMode,
      qa_allowed: qaAllowed,
      production_allowed: productionAllowed,
      run_selected: false,
      write_authorized: false,
      workspace_id: workspaceId,
      lead_id: lead.id,
      lead_public_id: lead.public_id,
      lead_name: lead.name || lead.email || lead.public_id,
      routing_status: lead.routing_status,
      title: 'Follow up with ' + (lead.name || lead.email || lead.public_id),
      description: 'Auto-created by Follow-Up Engine v1. ' + lead.routing_status + ' lead inactive for ' + Math.floor(inactiveHours) + ' hours. ' + marker,
      automation_key: automationKey,
      priority: lead.routing_status === 'Hot' ? 'high' : 'medium',
      due_at: dueAt,
      inactivity_hours: Math.floor(inactiveHours),
      workspace_timezone: runtime.timezone,
      plan_code: runtime.plan_code,
      subscription_status: runtime.subscription_status,
      max_tasks_per_run: runtime.max_tasks_per_run,
      max_tasks_per_day: runtime.max_tasks_per_day,
      idempotency_marker: marker,
    },
  });
  candidateGroups.set(workspaceId, group);
  stats.eligible_candidates += 1;
}

for (const [workspaceId, runtime] of runtimeByWorkspace.entries()) {
  const stats = ensureStats(workspaceId);
  if (!runtime.valid_timezone) continue;
  const dayKey = localDayKey(now, runtime.timezone);
  const todayAutoTaskCount = (productionAutoTasksByWorkspace.get(workspaceId) || []).filter((task) => {
    const createdAt = task.created_at ? new Date(task.created_at) : null;
    if (!createdAt || Number.isNaN(createdAt.getTime())) return false;
    return localDayKey(createdAt, runtime.timezone) === dayKey;
  }).length;
  stats.today_auto_tasks = todayAutoTaskCount;
  stats.daily_capacity_remaining = Math.max(0, runtime.max_tasks_per_day - todayAutoTaskCount);
}

const perWorkspaceQueues = new Map();
for (const [workspaceId, group] of candidateGroups.entries()) {
  const runtime = runtimeByWorkspace.get(workspaceId);
  const stats = ensureStats(workspaceId);
  group.sort((a, b) => {
    const aHot = a.json.routing_status === 'Hot' ? 1 : 0;
    const bHot = b.json.routing_status === 'Hot' ? 1 : 0;
    if (aHot !== bHot) return bHot - aHot;
    return Number(b.json.inactivity_hours || 0) - Number(a.json.inactivity_hours || 0);
  });
  const perWorkspaceLimit = Math.min(runtime.max_tasks_per_run, stats.daily_capacity_remaining);
  const chosen = group.slice(0, perWorkspaceLimit);
  for (const candidate of chosen) candidate.json.run_selected = true;
  stats.selected_candidates = chosen.length;
  perWorkspaceQueues.set(workspaceId, chosen);
}

const workspaceIds = [...perWorkspaceQueues.keys()].sort();
const rotation = workspaceIds.length ? Math.floor(now.getTime() / 3600000) % workspaceIds.length : 0;
const rotatedWorkspaceIds = workspaceIds.length
  ? workspaceIds.slice(rotation).concat(workspaceIds.slice(0, rotation))
  : [];
const fairQueue = [];
let round = 0;
while (true) {
  let added = false;
  for (const workspaceId of rotatedWorkspaceIds) {
    const queue = perWorkspaceQueues.get(workspaceId) || [];
    if (round < queue.length) {
      fairQueue.push(queue[round]);
      added = true;
    }
  }
  if (!added) break;
  round += 1;
}

let writesRemaining = globalMaxWrites;
for (const candidate of fairQueue) {
  const modeAllowed = candidate.json.qa_allowed === true || candidate.json.production_allowed === true;
  const canWrite = Boolean(writeEnabled && modeAllowed && writesRemaining > 0);
  candidate.json.write_authorized = canWrite;
  candidate.json.global_max_writes_per_run = globalMaxWrites;
  if (canWrite) {
    writesRemaining -= 1;
    ensureStats(candidate.json.workspace_id).authorized_candidates += 1;
  }
}

const allCandidates = [];
for (const group of candidateGroups.values()) {
  for (const candidate of group) {
    candidate.json.global_max_writes_per_run = globalMaxWrites;
    allCandidates.push(candidate);
  }
}

if (allCandidates.length === 0) {
  return [{
    json: {
      create_task: false,
      write_enabled: writeEnabled,
      production_mode: productionMode,
      qa_mode: qaMode,
      write_authorized: false,
      global_max_writes_per_run: globalMaxWrites,
      workspace_stats: Array.from(workspaceStats.values()),
      fair_rotation_offset: rotation,
      message: 'No eligible follow-up candidates after workspace, entitlement, stage, staleness, task, and daily-cap checks.',
    },
  }];
}

allCandidates[0].json.workspace_stats = Array.from(workspaceStats.values());
allCandidates[0].json.fair_rotation_offset = rotation;
return allCandidates;

const rows = $input.all().map((item) => item.json);
const errors = rows.filter((row) => row.error);
const successes = rows.filter((row) => !row.error && (row.public_id || row.id));

return [{
  json: {
    ok: errors.length === 0,
    created_count: successes.length,
    error_count: errors.length,
    task_ids: successes.map((row) => row.public_id || row.id).filter(Boolean),
    errors: errors.map((row) => ({
      message: row.error?.message || row.error || 'Unknown create error',
      description: row.error?.description || null,
    })),
    message: errors.length
      ? 'Some follow-up writes were rejected or failed. Database guardrail or duplicate automation_key conflicts are fail-safe and should be reviewed in execution logs.'
      : 'Internal follow-up tasks created. No email, SMS, or calendar action was performed.',
  },
}];

const rows = $input.all().map((item) => item.json);
const eligible = rows.filter((row) => row.create_task === true);
const runSelected = eligible.filter((row) => row.run_selected === true);
const writeAuthorized = eligible.filter((row) => row.write_authorized === true);

let workspaceStats = [];
let fairRotationOffset = 0;
try {
  const buildItems = $items('Build Production-Safe Candidates').map((item) => item.json);
  const diagnosticRow = buildItems.find((row) => Array.isArray(row.workspace_stats));
  workspaceStats = diagnosticRow?.workspace_stats || [];
  fairRotationOffset = diagnosticRow?.fair_rotation_offset || 0;
} catch {}

let scope = {};
try { scope = $('Build Eligible Workspace Scope').first().json || {}; } catch {}

return [{
  json: {
    ok: true,
    write_enabled: rows.some((row) => row.write_enabled === true),
    production_mode: rows.some((row) => row.production_mode === true),
    qa_mode: scope.qa_mode === true,
    qa_allowlist_configured: scope.qa_allowlist_configured === true,
    eligible_count: eligible.length,
    run_selected_count: runSelected.length,
    write_authorized_count: writeAuthorized.length,
    global_max_writes_per_run: rows[0]?.global_max_writes_per_run ?? 0,
    scoped_workspace_count: scope.scoped_workspace_count ?? 0,
    fair_rotation_offset: fairRotationOffset,
    scope_diagnostics: scope.scope_diagnostics || [],
    workspace_stats: workspaceStats,
    message: writeAuthorized.length
      ? 'Writes are authorized for a bounded subset. Database guardrails still enforce tenant consistency, production entitlement, daily caps, and atomic idempotency.'
      : 'Shadow/dry-run: candidates were evaluated but no write is authorized.',
    candidates: eligible.map((row) => ({
      workspace_id: row.workspace_id,
      lead_public_id: row.lead_public_id,
      routing_status: row.routing_status,
      priority: row.priority,
      inactivity_hours: row.inactivity_hours,
      due_at: row.due_at,
      plan_code: row.plan_code,
      qa_allowed: row.qa_allowed === true,
      production_allowed: row.production_allowed === true,
      run_selected: row.run_selected === true,
      write_authorized: row.write_authorized === true,
      automation_key: row.automation_key,
    })),
  },
}];

const candidates = $items('Build Production-Safe Candidates').map((item) => item.json);
const authorized = candidates.filter((row) => row.create_task === true && row.write_authorized === true && row.workspace_id);
const results = $items('Create Internal Follow-up Task').map((item) => item.json);
const executionId = String($execution.id || '');
const nowIso = new Date().toISOString();
const byWorkspace = new Map();

function ensure(workspaceId) {
  const key = String(workspaceId);
  if (!byWorkspace.has(key)) {
    byWorkspace.set(key, { workspace_id: key, selected_count: 0, created_count: 0, error_count: 0 });
  }
  return byWorkspace.get(key);
}

for (const candidate of authorized) {
  ensure(candidate.workspace_id).selected_count += 1;
}

for (let index = 0; index < authorized.length; index += 1) {
  const candidate = authorized[index];
  const result = results[index] || {};
  const stats = ensure(candidate.workspace_id);
  const failed = Boolean(result.error) || (!result.public_id && !result.id);
  if (failed) stats.error_count += 1;
  else stats.created_count += 1;
}

return Array.from(byWorkspace.values()).map((stats) => {
  const failed = stats.error_count > 0;
  const runRef = executionId || nowIso;
  return {
    json: {
      workspace_id: stats.workspace_id,
      automation_key: 'follow-up-engine',
      automation_name: 'Follow-Up Engine',
      source: 'n8n',
      trigger_type: 'scheduled',
      status: failed ? 'failed' : 'succeeded',
      run_ref: runRef,
      correlation_key: 'follow-up-engine:' + runRef + ':' + stats.workspace_id,
      record_type: 'workspace',
      record_id: stats.workspace_id,
      attempt_number: 1,
      started_at: nowIso,
      finished_at: nowIso,
      error_code: failed ? 'FOLLOW_UP_TASK_CREATE_FAILED' : null,
      error_message: failed ? 'One or more authorized follow-up task writes failed or returned no created task.' : null,
      selected_count: stats.selected_count,
      created_count: stats.created_count,
      error_count: stats.error_count,
    },
  };
});

const candidates = $items('Build Production-Safe Candidates').map((item) => item.json);
const executionId = String($execution.id || '');
const nowIso = new Date().toISOString();
const runRef = executionId || nowIso;

let scope = {};
try { scope = $('Build Eligible Workspace Scope').first().json || {}; } catch {}

const authorizedWorkspaceIds = new Set(
  candidates
    .filter((row) => row.create_task === true && row.write_authorized === true && row.workspace_id)
    .map((row) => String(row.workspace_id)),
);

const diagnosticRow = candidates.find((row) => Array.isArray(row.workspace_stats));
const workspaceStats = Array.isArray(diagnosticRow?.workspace_stats) ? diagnosticRow.workspace_stats : [];
const statsByWorkspace = new Map(
  workspaceStats
    .filter((row) => row?.workspace_id)
    .map((row) => [String(row.workspace_id), row]),
);

const scopedWorkspaceIds = Array.isArray(scope.scoped_workspace_ids)
  ? scope.scoped_workspace_ids.map(String)
  : [];
const workspaceIds = [...new Set(scopedWorkspaceIds)];

return workspaceIds
  .filter((workspaceId) => !authorizedWorkspaceIds.has(workspaceId))
  .map((workspaceId) => {
    const stats = statsByWorkspace.get(workspaceId) || {};
    return {
      json: {
        workspace_id: workspaceId,
        automation_key: 'follow-up-engine',
        automation_name: 'Follow-Up Engine',
        source: 'n8n',
        trigger_type: 'scheduled',
        status: 'suppressed',
        run_ref: runRef,
        correlation_key: 'follow-up-engine:' + runRef + ':' + workspaceId,
        record_type: 'workspace',
        record_id: workspaceId,
        attempt_number: 1,
        started_at: nowIso,
        finished_at: nowIso,
        error_code: null,
        error_message: null,
        suppression_reason: stats.skip_reason || 'no_authorized_follow_up_write',
        scanned_leads: Number(stats.scanned_leads || 0),
        eligible_candidates: Number(stats.eligible_candidates || 0),
        selected_candidates: Number(stats.selected_candidates || 0),
        authorized_candidates: Number(stats.authorized_candidates || 0),
      },
    };
  });
